using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint;
public sealed class DocumentaryMediaProviderRegistryTests
{
 [Fact] public void Execute_requires_all_six_ports_but_plan_only_requires_none(){var request=DocumentaryMediaPipelineFixture.Request(DocumentaryMediaPipelineFixture.Orion());var rejected=new DocumentaryMediaPipelineOrchestrator(new()).Execute(request);Assert.Equal(DocumentaryMediaPipelineStatus.Rejected,rejected.Status);Assert.Contains(DocumentaryMediaPipelineRejectionReason.ProviderUnavailable,rejected.RejectionReasons);Assert.Null(rejected.ExecutionRecord);var planned=new DocumentaryMediaPipelineOrchestrator(new()).Execute(request with{Policy=DocumentaryMediaPipelineFixture.PlanOnly()});Assert.Equal(DocumentaryMediaPipelineStatus.Planned,planned.Status);}
 [Fact] public void Registry_is_constructor_injected_and_stable(){var type=typeof(DocumentaryMediaPipelineOrchestrator);Assert.Single(type.GetConstructors());Assert.Equal(typeof(DocumentaryMediaProviderRegistry),Assert.Single(type.GetConstructors()[0].GetParameters()).ParameterType);Assert.Empty(type.GetFields(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static));}
 [Fact] public void Invalid_request_invokes_no_provider(){var fake=new DocumentaryMediaPipelineFakeProviders();var q=DocumentaryMediaPipelineFixture.Request(DocumentaryMediaPipelineFixture.Orion()) with{Metadata=new DocumentaryMediaPipelineMetadata(DocumentaryMediaPipelineFixture.Timestamp,DocumentaryMediaPipelineFixture.Creator,"wrong","execution")};var r=new DocumentaryMediaPipelineOrchestrator(fake.Registry).Execute(q);Assert.Equal(DocumentaryMediaPipelineStatus.Rejected,r.Status);Assert.Empty(fake.VisualRequests);Assert.Empty(fake.NarrationRequests);Assert.Empty(fake.SubtitleRequests);Assert.Empty(fake.SceneRequests);Assert.Empty(fake.VariantRequests);Assert.Empty(fake.VerificationRequests);}
}
